import * as THREE from 'three/webgpu';
import { texture, positionGeometry, normalGeometry, mul, add } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  // Load textures (assumed synchronous from cache)
  const colorMap = ctx.textureLoader(config.assets.imageUrl);
  const depthMap = ctx.textureLoader(config.assets.depthMapUrl);

  // Tessellated plane geometry with 64x64 segments
  const geometry = new THREE.PlaneGeometry(1, 1, 64, 64);

  // Build TSL displacement node
  const depthNode = texture(depthMap).r.mul(0.1); // scale factor
  const displaceVec = normalGeometry.mul(depthNode);
  const displacedPos = positionGeometry.add(displaceVec);

  // Material with machined-metal PBR parameters
  const material = new THREE.MeshNodeMaterial();
  material.colorNode = texture(colorMap);
  material.roughness = 0.5;
  material.metalness = 0.55;
  material.clearcoat = 0.25;
  material.envMapIntensity = 1.0;
  material.positionNode = displacedPos;
  material.side = THREE.DoubleSide;

  // Assemble mesh
  const mesh = new THREE.Mesh(geometry, material);
  const sp = config.scenePlacement;
  mesh.position.set(sp.position.x, sp.position.y, sp.position.z);
  mesh.rotation.set(sp.rotation.x, sp.rotation.y, sp.rotation.z);
  mesh.scale.set(sp.scale.x, sp.scale.y, sp.scale.z);

  // Apply all cinematic primitives
  (config.cinematicPrimitives || []).forEach(prim => {
    ctx.primitives[prim.name](mesh, prim.params);
  });

  // Store original Y for hover animation
  const originalY = mesh.position.y;

  // Weighted‑settle entrance (overshoot 1.04 → 1.0)
  const entranceTL = gsap.timeline();
  mesh.scale.set(0.8, 0.8, 0.8);
  entranceTL.to(mesh.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.6, ease: 'power4.out' })
           .to(mesh.scale, { x: 1, y: 1, z: 1, duration: 0.3, ease: 'power4.out' });

  // Cleanup handler
  mesh.userData.cleanup = () => {
    entranceTL.kill();
    gsap.killTweensOf(mesh.position);
    gsap.killTweensOf(mesh.scale);
    geometry.dispose();
    material.dispose();
    colorMap.dispose();
    depthMap.dispose();
  };

  // Interaction handlers (hover + click)
  mesh.userData.handlers = {
    hover: () => {
      gsap.to(mesh.position, {
        y: originalY + 0.15,
        duration: 0.7,
        ease: 'power3.out',
        overwrite: 'auto'
      });
    },
    hoverend: () => {
      gsap.to(mesh.position, {
        y: originalY,
        duration: 0.7,
        ease: 'power3.out',
        overwrite: 'auto'
      });
    },
    click: () => {
      if (ctx.emit) ctx.emit('hub-pricing.select');
    }
  };

  return mesh;
}
